package ro.leo.visual;
import android.app.*;import android.content.*;import android.media.AudioManager;
/** Single opt-in daily interval. Captures and restores only the audio state it owns. */
final class SoundSchedule {
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("sound-schedule",0);}
 private static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,874,new Intent(c,SoundScheduleReceiver.class).setAction("ro.leo.visual.SOUND_BOUNDARY"),PendingIntent.FLAG_UPDATE_CURRENT);}
 static void manual(Context c){SharedPreferences p=prefs(c);if(p.getBoolean("active",false)){restore(c);p.edit().putLong("skip-until",SoundScheduleMath.next(System.currentTimeMillis(),p.getInt("start",1320),p.getInt("end",420))).commit();}}
 static void sync(Context c){SharedPreferences p=prefs(c);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);am.cancel(alarm(c));long now=System.currentTimeMillis();int start=p.getInt("start",1320),end=p.getInt("end",420);boolean enabled=p.getBoolean("enabled",false);boolean active=enabled&&now>=p.getLong("skip-until",0)&&SoundScheduleMath.active(now,start,end,p.getInt("days",127));try{if(active&&!p.getBoolean("active",false))enter(c);else if(!active&&p.getBoolean("active",false))restore(c);}catch(RuntimeException e){FaultLedger.record(c,"SoundSchedule",e);try{restore(c);}catch(RuntimeException failed){FaultLedger.record(c,"SoundRestore",failed);}prefs(c).edit().putBoolean("enabled",false).commit();enabled=false;}if(enabled)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,SoundScheduleMath.next(now,start,end),alarm(c));}
 private static void enter(Context c){SharedPreferences p=prefs(c);NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(!nm.isNotificationPolicyAccessGranted())throw new IllegalStateException();AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);NotificationManager.Policy old=nm.getNotificationPolicy();if(!p.edit().putInt("old-filter",nm.getCurrentInterruptionFilter()).putInt("old-mode",a.getRingerMode()).putInt("old-alarm",a.getStreamVolume(AudioManager.STREAM_ALARM)).putInt("old-fm",FmService.instance!=null?FmService.volume:-1).putInt("old-ring",a.getStreamVolume(AudioManager.STREAM_RING)).putInt("old-music",a.getStreamVolume(AudioManager.STREAM_MUSIC)).putInt("old-categories",old.priorityCategories).putInt("old-calls",old.priorityCallSenders).putInt("old-messages",old.priorityMessageSenders).putInt("old-visual",old.suppressedVisualEffects).putBoolean("active",true).commit())throw new IllegalStateException();boolean calls=p.getBoolean("calls",false),alarms=p.getBoolean("alarms",true);int categories=calls?NotificationManager.Policy.PRIORITY_CATEGORY_CALLS:0;nm.setNotificationPolicy(new NotificationManager.Policy(categories,NotificationManager.Policy.PRIORITY_SENDERS_STARRED,NotificationManager.Policy.PRIORITY_SENDERS_ANY,old.suppressedVisualEffects));a.setRingerMode(AudioManager.RINGER_MODE_NORMAL);nm.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_PRIORITY);if(!alarms)a.setStreamVolume(AudioManager.STREAM_ALARM,0,0);if(p.getBoolean("night",true)){a.setStreamVolume(AudioManager.STREAM_MUSIC,0,0);if(FmService.instance!=null)FmService.instance.setVolume(0);}}
 static boolean allowAlarm(Context c,int id){SharedPreferences p=prefs(c);return !p.getBoolean("active",false)||p.getBoolean("alarms",true)&&(!p.getBoolean("selected-alarms",false)||id<0||p.getStringSet("alarm-ids",java.util.Collections.<String>emptySet()).contains(""+id));}
 static void restore(Context c){SharedPreferences p=prefs(c);if(!p.getBoolean("active",false))return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(!nm.isNotificationPolicyAccessGranted())throw new IllegalStateException();AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);nm.setNotificationPolicy(new NotificationManager.Policy(p.getInt("old-categories",0),p.getInt("old-calls",0),p.getInt("old-messages",0),p.getInt("old-visual",0)));nm.setInterruptionFilter(p.getInt("old-filter",NotificationManager.INTERRUPTION_FILTER_ALL));a.setRingerMode(p.getInt("old-mode",AudioManager.RINGER_MODE_NORMAL));a.setStreamVolume(AudioManager.STREAM_RING,Math.min(a.getStreamMaxVolume(AudioManager.STREAM_RING),p.getInt("old-ring",0)),0);a.setStreamVolume(AudioManager.STREAM_MUSIC,Math.min(a.getStreamMaxVolume(AudioManager.STREAM_MUSIC),p.getInt("old-music",0)),0);a.setStreamVolume(AudioManager.STREAM_ALARM,Math.min(a.getStreamMaxVolume(AudioManager.STREAM_ALARM),p.getInt("old-alarm",0)),0);if(p.getBoolean("night",true)&&p.getInt("old-fm",-1)>=0&&FmService.instance!=null)FmService.instance.setVolume(p.getInt("old-fm",8));if(!p.edit().putBoolean("active",false).commit())throw new IllegalStateException();}
}
